<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { adminApi } from '../api/admin'
import PaginationBar from '../components/PaginationBar.vue'
const logs=ref<any[]>([]),total=ref(0),action=ref(''),resourceType=ref(''),loading=ref(false),error=ref(''),selected=ref<any>(null),page=ref(1),pageSize=ref(10)
const actionLabel=(value:string)=>({submit:'提交',settle:'审核通过',reject:'审核拒绝',approve:'通过',update:'更新',soft_delete:'软删除',restore:'恢复',update_roles:'修改角色',update_status:'更新状态',create:'创建',grant:'授予授权',revoke:'撤销授权',assign:'指派',close:'关闭',handle:'处理',request_revision:'要求修改',batch_update:'批量更新',update_permissions:'修改权限',create_draft:'创建草稿',confirm_draft:'确认草稿',customer_material_submitted:'客户提交材料',customer_supplement:'客户补充',upload_attachment:'上传附件',enqueue:'入队',outbox_event_retry:'重试发件箱事件',risk_action:'风险处置',daily_aml_scan:'每日 AML 扫描','customer_agent.intent_shadow_evaluated':'意图评估','data_analysis.template_executed':'数据分析模板已执行','data_analysis.template_rejected':'数据分析模板已拒绝','customer_service.bounded_react_executed':'客服执行完成'} as Record<string,string>)[value]||value
const statusLabel=(value:string)=>({pending_confirmation:'待客户确认',pending_review:'待审核',executed:'已成交',settled:'已结算',rejected:'已拒绝',cancelled:'已取消',open:'待处理',resolved:'已解决',executing:'执行中',risk_hold:'风险冻结',pending_customer:'待客户补充',acknowledged:'已确认',investigating:'调查中',report_pending:'待上报',dismissed:'已驳回',closed:'已关闭',expired:'已过期',in_progress:'处理中',assigned:'已指派',waiting_human:'等待人工',paused:'已暂停',human_active:'人工处理中',pending_customer_confirmation:'待客户确认',customer_confirmed:'客户已确认',submitted:'已提交',approved:'已通过',active:'生效',restricted:'受限',pending:'待处理',success:'成功',dead:'失败',failed:'失败'} as Record<string,string>)[value]||value||'—'
const resourceTypeLabel=(value:string)=>({order:'订单',business_operation:'业务操作',risk_alert:'风险预警',user:'用户',product:'产品',redeem:'赎回',transfer:'转账',customer_profile:'客户资料',enterprise_verification:'企业认证',risk_assessment:'风险评估',advisor_operation_draft:'顾问操作草稿',advisor_authorization:'顾问授权',work_order:'工单',customer_service_session:'客服会话',customer_service_conversation:'客服对话',data_catalog_table:'数据目录表',data_catalog_column:'数据目录字段',data_catalog_example_query:'数据目录示例查询',data_catalog_embedding:'数据目录向量',aml_batch_run:'AML 批次运行',outbox_event:'发件箱事件',role:'角色',bad_case:'不良案例',natural_language_order_draft:'自然语言订单草稿',notification:'通知'} as Record<string,string>)[value]||value
async function load(){loading.value=true;try{const r=(await adminApi.auditLogs(action.value,resourceType.value,pageSize.value,(page.value-1)*pageSize.value)).data.data;logs.value=r.items;total.value=r.total}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{loading.value=false}}
function showDetail(log:any){selected.value=log}function go(n:number){page.value=Math.max(1,n);load()}function changeSize(n:number){pageSize.value=n;page.value=1;load()}onMounted(load)
</script>
<template><section class="table-module"><div class="module-header"><div><span class="module-kicker">审计记录</span><h2>审计查询</h2><p>展示客户、业务对象和状态，唯一标识仅用于追踪。</p></div><span class="table-summary">共 {{total}} 条</span></div><div class="module-tools"><select v-model="action" @change="load"><option value="">全部操作</option><option value="submit">提交</option><option value="settle">审核通过</option><option value="reject">审核拒绝</option><option value="soft_delete">软删除</option><option value="restore">恢复</option></select><select v-model="resourceType" @change="load"><option value="">全部对象</option><option value="order">订单</option><option value="business_operation">业务操作</option><option value="risk_alert">风险预警</option><option value="user">用户</option><option value="product">产品</option></select><button class="table-action" @click="load">刷新</button></div><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取审计记录…</div><div v-else class="module-table-wrap wide-table"><table class="admin-table compact-table"><thead><tr><th>时间</th><th>操作</th><th>客户</th><th>业务对象</th><th>状态</th><th>操作人</th><th>详情</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td class="time-cell">{{log.created_at}}</td><td>{{actionLabel(log.action)}}</td><td><strong>{{log.customer_name||'—'}}</strong><small class="audit-sub">{{log.customer_username||''}}</small></td><td><strong>{{resourceTypeLabel(log.business_type)||log.resource_name||log.resource_type}}</strong><small class="audit-sub">{{log.product_name||log.business_reference}}</small></td><td><span class="table-tag">{{statusLabel(log.business_status)}}</span></td><td>{{log.actor_name||'系统'}}</td><td><button class="table-action" @click="showDetail(log)">查看详情</button></td></tr><tr v-if="!logs.length"><td colspan="7" class="table-empty">暂无审计记录</td></tr></tbody></table></div><PaginationBar :page="page" :page-size="pageSize" :total="total" @change="go" @size-change="changeSize"/><Teleport to="body"><div v-if="selected" class="admin-modal-backdrop" @click.self="selected=null"><div class="admin-modal detail-modal"><div class="modal-header"><div><span class="module-kicker">审计详情</span><h3>审计记录详情</h3></div><button class="modal-close" @click="selected=null">×</button></div><dl class="detail-grid"><dt>时间</dt><dd>{{selected.created_at}}</dd><dt>操作</dt><dd>{{actionLabel(selected.action)}}</dd><dt>客户</dt><dd>{{selected.customer_name||'—'}} {{selected.customer_username?`（${selected.customer_username}）`:''}}</dd><dt>业务类型</dt><dd>{{resourceTypeLabel(selected.business_type)||selected.business_type||selected.resource_type}}</dd><dt>业务对象</dt><dd>{{selected.product_name||selected.business_reference||selected.resource_name}}</dd><dt>业务状态</dt><dd>{{statusLabel(selected.business_status)}}</dd><dt>资源 ID</dt><dd class="mono">{{selected.resource_id}}</dd><dt>操作人</dt><dd>{{selected.actor_name||'系统'}}</dd><dt>详情</dt><dd class="detail-json">{{selected.detail||'无'}}</dd></dl></div></div></Teleport></section></template>
